package net.dawson.adorablehamsterpets.flute;

import net.minecraft.util.Mth;

public final class FlutePerformancePolicy {
    private FlutePerformancePolicy() {
    }

    public static boolean canStart(boolean alreadyActive, boolean validInitiatingStack, boolean activeNormalRiff, boolean antiSpamCooldownActive) {
        return validInitiatingStack && !antiSpamCooldownActive && (!alreadyActive || activeNormalRiff);
    }

    public static RepeatAction repeatAction(long elapsedTicks, long totalDurationTicks, int layeringThresholdPercent) {
        int clampedThreshold;
        if (totalDurationTicks <= 0L) {
            return RepeatAction.LAYER;
        }
        long clampedElapsed = Math.max(0L, Math.min(elapsedTicks, totalDurationTicks));
        return clampedElapsed * 100L >= totalDurationTicks * (long)(clampedThreshold = Mth.m_14045_((int)layeringThresholdPercent, (int)0, (int)100)) ? RepeatAction.LAYER : RepeatAction.REPLACE;
    }

    public static Mode selectMode(boolean hasEligibleTarget, boolean hasAvailableSlot, boolean targetReserved) {
        return hasEligibleTarget && hasAvailableSlot && !targetReserved ? Mode.SHOULDER_CALL : Mode.NORMAL;
    }

    public static boolean remainsBound(boolean playerAlive, boolean sameDimension, boolean sameStack, boolean matchingFluteVariant) {
        return playerAlive && sameDimension && sameStack && matchingFluteVariant;
    }

    public static String sanitizePreviousGoalName(String goalName) {
        if (goalName == null || goalName.equals("HamsterLookAtEntityGoal") || goalName.equals("HamsterLookAroundGoal") || goalName.equals("FluteMountResponse")) {
            return "None";
        }
        return goalName;
    }

    public static enum RepeatAction {
        REPLACE,
        LAYER;

    }

    public static enum Mode {
        NORMAL,
        SHOULDER_CALL;

    }
}

