public final class FluteTrainingPolicy {
    public static final int UNTRAINED_DELAY_TICKS = 60;
    public static final int MASTERED_DELAY_TICKS = 20;
    private static final int DELAY_RANGE_TICKS = 40;

    private FluteTrainingPolicy() {
    }

    public static int responseDelayTicks(int successfulMounts, int masteryTarget) {
        int safeTarget = Math.max(1, masteryTarget);
        int progress = Mth.m_14045_((int)successfulMounts, (int)0, (int)safeTarget);
        int improvement = (int)Math.round((double)progress * 40.0 / (double)safeTarget);
        return Mth.m_14045_((int)(60 - improvement), (int)20, (int)60);
    }

    public static Tier tier(int successfulMounts, int masteryTarget) {
        if (successfulMounts <= 0) {
            return Tier.UNTRAINED;
        }
        int safeTarget = Math.max(1, masteryTarget);
        if (successfulMounts >= safeTarget) {
            return Tier.ATTUNED;
        }
        double progress = (double)successfulMounts / (double)safeTarget;
        if (progress >= 0.5) {
            return Tier.RESPONSIVE;
        }
        if (progress >= 0.25) {
            return Tier.LEARNING;
        }
        return Tier.UNTRAINED;
    }

    public static enum Tier {
        UNTRAINED,
        LEARNING,
        RESPONSIVE,
        ATTUNED;

    }
}

