package net.dawson.adorablehamsterpets.integration.iris;

import dev.architectury.platform.Platform;
import net.dawson.adorablehamsterpets.AdorableHamsterPets;
import net.dawson.adorablehamsterpets.client.render.HamsterPBRTexture;
import net.irisshaders.iris.texture.pbr.loader.PBRTextureLoader;
import net.irisshaders.iris.texture.pbr.loader.PBRTextureLoaderRegistry;
import net.minecraft.client.renderer.texture.AbstractTexture;
import net.minecraft.server.packs.resources.ResourceManager;

public class IrisIntegration {
    public static void init() {
        if (Platform.isModLoaded((String)"iris")) {
            try {
                IrisWrapper.registerPbrLoader();
                AdorableHamsterPets.LOGGER.info("[AHP] Successfully integrated with Iris PBR registry.");
            }
            catch (Throwable t) {
                AdorableHamsterPets.LOGGER.error("[AHP] Failed to integrate with Iris PBR registry.", t);
            }
        }
    }

    private static class IrisWrapper {
        private IrisWrapper() {
        }

        static void registerPbrLoader() {
            PBRTextureLoaderRegistry.INSTANCE.register(HamsterPBRTexture.class, (PBRTextureLoader)new PBRTextureLoader<HamsterPBRTexture>(){

                public void load(HamsterPBRTexture texture, ResourceManager resourceManager, PBRTextureLoader.PBRTextureConsumer consumer) {
                    if (texture.getNormalTexture() != null) {
                        consumer.acceptNormalTexture((AbstractTexture)texture.getNormalTexture());
                    }
                    if (texture.getSpecularTexture() != null) {
                        consumer.acceptSpecularTexture((AbstractTexture)texture.getSpecularTexture());
                    }
                }
            });
        }
    }
}

