import snownee.jade.api.IWailaCommonRegistration;
import snownee.jade.api.IWailaPlugin;
import snownee.jade.api.WailaPlugin;

@WailaPlugin
public final class AHPJadePlugin
implements IWailaPlugin {
    public void registerClient(IWailaClientRegistration registration) {
        registration.registerBlockComponent((IBlockComponentProvider)WildBushComponentProvider.INSTANCE, WildCucumberBushBlock.class);
        registration.registerBlockComponent((IBlockComponentProvider)WildBushComponentProvider.INSTANCE, WildGreenBeanBushBlock.class);
        registration.registerBlockComponent((IBlockComponentProvider)HamsterBedComponentProvider.INSTANCE, HamsterBedBlock.class);
        registration.usePickedResult((Block)ModBlocks.HAMSTER_BED.get());
        registration.registerEntityComponent((IEntityComponentProvider)HamsterGeneticsComponentProvider.INSTANCE, HamsterEntity.class);
        registration.registerEntityComponent((IEntityComponentProvider)HamsterDebugComponentProvider.INSTANCE, HamsterEntity.class);
        registration.addTooltipCollectedCallback((tooltip, accessor) -> {
            EntityAccessor entityAccessor;
            if (accessor instanceof EntityAccessor && (entityAccessor = (EntityAccessor)accessor).getEntity() instanceof HamsterEntity) {
                boolean hideDueToSneak;
                boolean playerSneaking = entityAccessor.getPlayer().m_6144_();
                boolean bl = hideDueToSneak = Configs.AHP_UI.requireSneakForDefaultJadeInfo && !playerSneaking;
                if (!Configs.AHP_UI.showJadeEntityName || hideDueToSneak) {
                    tooltip.remove(new ResourceLocation("jade", "object_name"));
                }
                if (!Configs.AHP_UI.showJadeEntityHealth || hideDueToSneak) {
                    tooltip.remove(new ResourceLocation("minecraft", "entity_health"));
                }
                if (!Configs.AHP_UI.showJadeGrowthTime || hideDueToSneak) {
                    tooltip.remove(new ResourceLocation("minecraft", "mob_growth"));
                }
                if (!Configs.AHP_UI.showJadeOwner || hideDueToSneak) {
                    tooltip.remove(new ResourceLocation("minecraft", "animal_owner"));
                }
                if (!Configs.AHP_UI.showJadeInventory || hideDueToSneak) {
                    tooltip.remove(new ResourceLocation("minecraft", "item_storage"));
                }
            }
        });
    }

    public void register(IWailaCommonRegistration registration) {
        registration.registerBlockDataProvider((IServerDataProvider)HamsterBedComponentProvider.INSTANCE, HamsterBedBlockEntity.class);
        registration.registerEntityDataProvider((IServerDataProvider)HamsterGeneticsComponentProvider.INSTANCE, HamsterEntity.class);
        registration.registerEntityDataProvider((IServerDataProvider)HamsterDebugComponentProvider.INSTANCE, HamsterEntity.class);
    }
}

