import net.dawson.adorablehamsterpets.util.DynamicFoodUtil;
import net.minecraft.network.chat.Component;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.TooltipFlag;
import net.minecraft.world.level.Level;
import org.jetbrains.annotations.Nullable;

public class ConfigurableFoodItem
extends Item {
    private final Supplier<Integer> nutritionSupplier;
    private final Supplier<Float> saturationSupplier;
    private final int defaultNutrition;
    private final float defaultSaturation;
    private final String tooltipBaseKey;

    public ConfigurableFoodItem(Item.Properties settings, Supplier<Integer> nutritionSupplier, Supplier<Float> saturationSupplier, int defaultNutrition, float defaultSaturation, String tooltipBaseKey) {
        super(settings);
        this.nutritionSupplier = nutritionSupplier;
        this.saturationSupplier = saturationSupplier;
        this.defaultNutrition = defaultNutrition;
        this.defaultSaturation = defaultSaturation;
        this.tooltipBaseKey = tooltipBaseKey;
    }

    public void m_7373_(ItemStack stack, @Nullable Level world, List<Component> tooltip, TooltipFlag context) {
        DynamicFoodUtil.appendTooltip(tooltip, this.tooltipBaseKey, this.nutritionSupplier.get(), this.saturationSupplier.get().floatValue(), this.defaultNutrition, this.defaultSaturation);
        super.m_7373_(stack, world, tooltip, context);
    }
}

